import itertools

fixed={7:2,9:1,12:4}

solutions=[]
for perm in itertools.product(range(1,5), repeat=16):
    ok=True
    for idx,val in fixed.items():
        if perm[idx]!=val:
            ok=False;break
    if not ok: continue
    # rows
    for r in range(4):
        row=perm[r*4:(r+1)*4]
        if set(row)!=set([1,2,3,4]):
            ok=False;break
    if not ok: continue
    # cols
    for c in range(4):
        col=[perm[r*4+c] for r in range(4)]
        if set(col)!=set([1,2,3,4]):
            ok=False;break
    if not ok: continue
    # blocks 2x2
    for br in range(0,4,2):
        for bc in range(0,4,2):
            block=[perm[r*4+ c] for r in (br,br+1) for c in (bc,bc+1)]
            if set(block)!=set([1,2,3,4]):
                ok=False;break
        if not ok: break
    if ok:
        solutions.append(perm)
        break
print(solutions[:1])
